set -eu
runuser -u postgres -- psql -v ON_ERROR_STOP=1 <<'SQL'
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'replicator') THEN
    CREATE ROLE replicator WITH LOGIN REPLICATION;
  END IF;
END
$do$;
SELECT pg_create_physical_replication_slot('node2_slot')
WHERE NOT EXISTS (SELECT 1 FROM pg_replication_slots WHERE slot_name = 'node2_slot');
SELECT pg_create_physical_replication_slot('node3_slot')
WHERE NOT EXISTS (SELECT 1 FROM pg_replication_slots WHERE slot_name = 'node3_slot');
SQL
runuser -u postgres -- psql -X -P pager=off -c "SELECT rolname, rolcanlogin, rolreplication FROM pg_roles WHERE rolname='replicator';"
runuser -u postgres -- psql -X -P pager=off -c "SELECT slot_name, slot_type, active FROM pg_replication_slots ORDER BY slot_name;"

