set -eu
runuser -u postgres -- psql -X -v ON_ERROR_STOP=1 -P pager=off <<'SQL'
BEGIN;
CREATE TABLE IF NOT EXISTS public.replication_evidence (
  evidence_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source_node text NOT NULL,
  marker text NOT NULL UNIQUE,
  committed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
INSERT INTO public.replication_evidence(source_node, marker)
VALUES ('node1', 'committed-change-streamed-to-both-standbys')
ON CONFLICT (marker) DO UPDATE SET committed_at = clock_timestamp();
COMMIT;
SELECT evidence_id, source_node, marker, committed_at
FROM public.replication_evidence
ORDER BY evidence_id;
SELECT pg_current_wal_lsn() AS primary_wal_lsn;
SQL

